import sys

def main():
    d = sys.stdin.read().split()
    n = int(d[0])
    streak = {}
    ans = 0
    for i in range(n):
        name, status = d[1 + 2 * i], d[2 + 2 * i]
        if status == 'error':
            c = streak.get(name, 0) + 1
            if c == 3:
                ans += 1
                c = 0
            streak[name] = c
        else:
            streak[name] = 0
    print(ans)

